// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.leo;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Test;

/**
 * {@link LeoEvidence#bestOf(java.util.Collection)} ranks evidence kinds by precedence, but a candidate that carries no
 * trust at all (zero confidence, zero evidence) must not outrank well-evidenced candidates of a lower-ranked kind.
 */
class LeoEvidenceRankingTest {

	@Test
	void zeroConfidenceSketchMustNotOutrankWellEvidencedFeedback() {
		LeoEvidence sketch = LeoEvidence.queryLocalVirtualSketch(1_000_000.0d, 1_000_000.0d, 0.0d, 0L, "sketch");
		LeoEvidence feedback = LeoEvidence.scalarCorrection(10.0d, 10.0d, 0.95d, 200L, "feedback");
		Optional<LeoEvidence> best = LeoEvidence.bestOf(List.of(sketch, feedback));
		assertEquals("feedback", best.orElseThrow().source(),
				"bestOf ranks by Kind before confidence: selected " + best.orElseThrow());
	}

	@Test
	void zeroEvidenceCountHistogramMustNotOutrankWellEvidencedFeedback() {
		LeoEvidence histogram = LeoEvidence.persistedFanoutHistogram(5_000.0d, 5_000.0d, 0.60d, 0L, "histogram");
		LeoEvidence feedback = LeoEvidence.scalarCorrection(10.0d, 10.0d, 0.95d, 200L, "feedback");
		assertSame(feedback, LeoEvidence.bestOf(List.of(histogram, feedback)).orElseThrow());
	}

	@Test
	void bestOfWithOnlyUntrustedCandidatesStillReturnsOne() {
		LeoEvidence sketch = LeoEvidence.queryLocalVirtualSketch(1_000.0d, 1_000.0d, 0.0d, 0L, "sketch");
		LeoEvidence feedback = LeoEvidence.scalarCorrection(10.0d, 10.0d, 0.0d, 0L, "feedback");
		Optional<LeoEvidence> best = LeoEvidence.bestOf(List.of(feedback, sketch));
		assertTrue(best.isPresent(), "a non-empty finite candidate list must always produce a winner");
		assertSame(sketch, best.orElseThrow(), "kind precedence still decides among equally untrusted candidates");
	}

	@Test
	void protectedExactEvidenceStillWinsOverTrustedLearnedEvidence() {
		LeoEvidence exact = LeoEvidence.exactFiniteRelation(2.0d, 2.0d, "exact");
		LeoEvidence feedback = LeoEvidence.scalarCorrection(10.0d, 10.0d, 0.95d, 200L, "feedback");
		LeoEvidence sketch = LeoEvidence.queryLocalVirtualSketch(1_000.0d, 1_000.0d, 0.0d, 0L, "sketch");
		assertSame(exact, LeoEvidence.bestOf(List.of(sketch, feedback, exact)).orElseThrow());
	}

	@Test
	void trustedSketchKeepsKindPrecedenceOverScalarCorrection() {
		LeoEvidence scalar = LeoEvidence.scalarCorrection(50.0d, 60.0d, 0.95d, 12L, "operator-feedback");
		LeoEvidence sketch = LeoEvidence.queryLocalVirtualSketch(400.0d, 430.0d, 0.75d, 1L, "virtual-sketch");
		assertSame(sketch, LeoEvidence.bestOf(List.of(scalar, sketch)).orElseThrow());
	}
}
